import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

fn bump(m: conc.Mutex<Int64>) -> Int64 {
    let _ = m.set(m.get() + 1i64)
    return m.get()
}

fn peek(m: conc.Mutex<Int64>) -> Int64 {
    return m.get()
}

fn read(m: conc.Mutex<Int64>) -> Int64 {
    let v = m.get()
    return v
}

pub fn main() effect io -> Result<(), AppError> {
    let c = conc.Mutex(0)
    let _ = c.set(41i64)
    io.println("a ${bump(c)}")
    io.println("b ${bump(c)}")
    io.println("peek ${peek(c)}")
    io.println("read ${read(c)}")
    io.println("inline ${peek(conc.Mutex(9i64))}")
    return Ok(())
}
